/bin/bash -lc "cat > ceo_policy.py <<'PY'
from collections import defaultdict
import re

from ceo_forecast import cash_forecast, is_enterprise


CAPACITY = [50000, 200000, 800000, 2500000, 8000000, 25000000, 80000000, 300000000]
CHANNELS = {\"S1\": \"referral_program\", \"S2\": \"content_marketing\", \"S3\": \"referral_program\"}
TARGETS = {\"S1\": 2.05, \"S2\": 2.25, \"S3\": 2.35, \"E1\": 1.85, \"E2\": 2.45, \"E3\": 2.40}
OFFERS = {
    \"E1\": [17, 20, 24, 27, 31, 35],
    \"E2\": [51, 57, 63, 71, 79, 89],
    \"E3\": [51, 59, 65, 72, 80, 93],
}


def dashboard_values(dashboard):
    global_quality = 0.20 + float(re.search(r\"global_bonus=([\\d.]+)\", dashboard).group(1))
    quality = {
        group: global_quality + float(bonus)
        for group, bonus in re.findall(
            r\""'^([A-Z0-9_]+)'"\\s+[\\d.]+\\s+[\\d.]+\\s+[\\d.]+\\s+\\+?([\\d.]+)\", dashboard, re.M
        )
    }
    prices = [float(p.replace(\",\", \"\")) for p in re.search(
        r\"Prices: A=\\"'$(['"\\d.,]+), B=\\"'$(['"\\d.,]+), C=\\"'$(['"\\d.,]+)\", dashboard
    ).groups()]
    tiers = list(map(int, re.search(r\"Model Tiers: A=(\\d), B=(\\d), C=(\\d)\", dashboard).groups()))
    quotas = list(map(int, re.search(r\"Quotas: A=(\\d+), B=(\\d+), C=(\\d+)\", dashboard).groups()))
    return global_quality, quality, prices, tiers, quotas


def group_stats(observation, quality, global_quality):
    groups = defaultdict(lambda: defaultdict(float))
    for row in observation[\"groups\"]:
        group = groups[row[\"group_id\"]]
        group[\"quality\"] = quality.get(row[\"group_id\"], global_quality)
        group[\"age\"] = observation[\"day\"] - (row[\"discovered_day\"] or 0)
    for row in observation[\"active\"]:
        group = groups[row[\"group_id\"]]
        for key in (\"customers\", \"seats\", \"mrr\"):
            group[key] += row[key]
    for row in observation[\"cohorts\"]:
        group = groups[row[\"group_id\"]]
        group[\"leads\"] += row[\"leads\"]
        group[\"signed\"] += row[\"signed\"]
        source = \"organic\" if row[\"channel\"] == \"network\" else \"paid\"
        group[source+\"_leads\"] += row[\"leads\"]
        group[source+\"_mrr\"] += row[\"mrr\"]
        group[source+\"_signed\"] += row[\"signed\"]
    for row in observation[\"churn\"]:
        groups[row[\"group_id\"]][\"churn\"] += row[\"customers\"]
    for row in observation[\"ads\"]:
        groups[row[\"group_id\"]][\"spend\"] += row[\"spend\"]
    for row in observation[\"issues\"]:
        groups[row[\"group_id\"]][\"issue_age\"] = row[\"age\"] or 0
        groups[row[\"group_id\"]][\"issues\"] = row[\"open\"]
    for row in observation[\"pending\"]:
        groups[row[\"group_id\"]][\"pending\"] += row[\"customers\"]
    return groups


def retail_prices(day, groups, prices, last_plan):
    s1, s3 = groups[\"S1\"], groups[\"S3\"]
    conversion = s1[\"signed\"] / max(1, s1[\"leads\"])
    churn = s1[\"churn\"] / max(1, s1[\"customers\"])
    if day < 112 and conversion >= 0.60 and churn < 0.025:
        prices[0] = min(37, prices[0] + 2)
        prices[1] = min(75, prices[1] + 5)
        prices[2] = min(171, prices[2] + 4)
    elif day > 112 and day < 430 and day % 21 == 0 and s1[\"quality\"] > 1.75:
        if conversion > 0.66 and churn < 0.026:
            prices[0] += 2
            prices[1] += 3
        elif conversion < 0.44 or churn > 0.047:
            prices[0] = max(27, prices[0]-2)
            prices[1] = max(57, prices[1]-3)
        if s3[\"signed\"] / max(1, s3[\"leads\"]) > 0.67 and s3[\"quality\"] > 2.1:
            prices[2] += 4
    return prices


def paid_budget(name, group, day, cash):
    last_daily = group[\"spend\"] / 7
    if is_enterprise(name):
        if name == \"E3\" or group[\"quality\"] < 1.14 or day > 469:
            return 0
        if group[\"organic_leads\"] > 55 or group[\"pending\"] > 140:
            return 0
        if name == \"E2\":
            return round(max(5200, min(20000, last_daily * 1.14)), -2)
        if name == \"E1\":
            return 4800
        return 4200 if group[\"organic_leads\"] < 24 else 0

    if group[\"quality\"] < 0.94:
        return 0
    if last_daily == 0:
        return 1800 if name not in CHANNELS and day < 450 and group[\"age\"] >= 14 else 0
    payback = group[\"paid_mrr\"] / max(1, group[\"spend\"])
    organic = group[\"organic_signed\"]
    budget_limit = {\"S1\": 34000, \"S2\": 23500, \"S3\": 25500}.get(name, 13500)
    if day > 475:
        budget_limit *= 0.6
    if payback > 2.3:
        budget = last_daily * (1.13 if cash > 1_900_000 else 1.02)
    elif payback > 1.35:
        budget = last_daily
    elif payback > 0.75 and day < 455:
        budget = last_daily * 0.72
    else:
        budget = last_daily * 0.35
    if organic > 7000 and group[\"customers\"] > 120000 and budget > 11500:
        budget *= 0.87
    if budget < 450 or (day >= 490 and payback < 1.25):
        return 0
    return round(min(budget_limit, budget), -2)


def strategy(observation, dashboard, last_plan, adjustments=None):
    day = observation[\"day\"]
    cash = observation[\"cash\"]
    global_quality, quality, old_prices, tiers, quotas = dashboard_values(dashboard)
    groups = group_stats(observation, quality, global_quality)
    prices = retail_prices(day, groups, old_prices.copy(), last_plan)
    individuals = int(sum(g[\"customers\"] for name,g in groups.items() if not is_enterprise(name)))
    seats = int(sum(g[\"seats\"] for name,g in groups.items() if is_enterprise(name)))
    new_customers = sum(g[\"signed\"] for name,g in groups.items() if not is_enterprise(name))
    churn = sum(g[\"churn\"] for name,g in groups.items() if not is_enterprise(name))
    daily_peak = max(r[\"usage\"] for r in observation[\"service\"])
    outstanding_seats = sum(r[\"seats\"] for r in observation[\"pending\"] if r[\"thread_type\"] == \"new_lead\")
    demand = daily_peak * (1.10 + max(0, (new_customers-churn) / max(1, individuals))) + 12*outstanding_seats
    capacity = next((tier for tier, value in enumerate(CAPACITY) if value >= demand), 7)
    if tiers[2] == 4 and groups[\"E2\"][\"quality\"] >= 1.23 and groups[\"E3\"][\"quality\"] >= 1.55:
        tiers[2] = 3
    development = 0
    if day < 457:
        development = 6500 if cash < 3_000_000 else min(24500, 9500 + 1800*(len(groups)-6))
    weighted_age = sum(g[\"issue_age\"] * g[\"customers\"] for name,g in groups.items()
                       if not is_enterprise(name)) / max(1, individuals)
    operations = max(1700, round(individuals * min(0.25, 0.115 + 0.032*weighted_age), -2))
    if day >= 497:
        operations = round(operations * 0.75, -2)
    targeted_ops, development_by_group, offers, in_app = {}, {}, {}, {}
    ads = defaultdict(dict)
    expected_acquisition = 0
    for name, group in groups.items():
        enterprise = is_enterprise(name)
        active = group[\"customers\"]
        q = group[\"quality\"]
        target = TARGETS.get(name, 2.18 if enterprise else 2.03)
        trailing_need = min(0.95, max(0, (day-116)*0.0026))
        gap = target + trailing_need - q
        if day < 478 and gap > 0.07:
            amount = min(26500 if name in (\"E2\", \"E3\") else 17000, gap*19000)
            if name.startswith(\"D_\") and group[\"age\"] < 14:
                amount = min(amount, 12500)
            if day > 414:
                amount *= max(0.1, (478-day)/64)
            development_by_group[name] = round(amount, -2)

        if enterprise:
            rule_prices = OFFERS.get(name, [34, 44, 54, 66, 80, 95])
            plan = \"C\"
            if name == \"E1\" and q > 1.46:
                plan = \"A\"
            elif q > (1.94 if name == \"E3\" else 2.16):
                plan = \"B\"
            if q > 2.35 and name "'!= "E1":
                rule_prices = [p + 6 for p in rule_prices]
            floor = {"A": 9, "B": 14, "C": 16}[plan]
            offers[name] = {"plan": plan, "prices": rule_prices, "counter_factor": 1,
                            "retention_factor": 1, "floor": floor}
            if active > 0:
                targeted_ops[name] = max(300, round((3.0 + 6.0*min(group["issue_age"], 3))*active, -2))
            if q > 1.5:
                in_app[name] = 0.12 if q < 2 else 0.30
        else:
            in_app[name] = 0.08 if q < 1.3 else 0.22 if q < 1.6 else 0.36 if q < 2 else 0.60
            if day > 490 and q > 1.75:
                in_app[name] = 0.88

        planned = paid_budget(name, group, day, cash)
        if planned and name == "S1":
            ads["content_marketing"][name] = round(planned * 0.41, -2)
            ads["referral_program"][name] = planned - ads["content_marketing"][name]
        elif planned:
            ads["linkedin" if enterprise else CHANNELS.get(name, "referral_program")][name] = planned
        if not enterprise:
            ratio = min(1.7, planned*7/max(1, group["spend"]))
            expected_acquisition += group["paid_mrr"]*ratio + group["organic_mrr"]*1.07

    undiscovered = max(0, 26-len(groups))
    discovery = 0
    if cash > 1_400_000 and undiscovered and day < 270:
        discovery = min(5 if cash < 2_700_000 else 10 if cash < 6_000_000 else 15,
                        max(2, undiscovered*3))
    plan = {
        "day": day, "prices": prices, "tiers": tiers, "quotas": quotas, "capacity": capacity,
        "spend": [operations, development], "dev": development_by_group, "ops": targeted_ops,
        "ads": dict(ads), "in_app": in_app, "offers": offers,
    }
    if discovery:
        plan["discover"] = discovery
    if adjustments:
        plan.update(adjustments)
    margin = sum(row["amount"] for row in observation["finance"])
    ad_spend = sum(sum(group.values()) for group in plan["ads"].values())
    q_spend = sum(plan["dev"].values()) + plan["spend"][1]
    book = sum(group["mrr"] for group in groups.values())
    ready = len(observation["enterprise"])
    a, b, c = plan["prices"]
    plan["rationale"] = (
        f"Day {day} cash is ${cash:,.0f} after weekly cash flow of ${margin:,.0f}. "
        f"The book has {individuals:,} retail customers, {seats:,} enterprise seats and ${book:,.0f} of monthly billings. "
        f"Set retail prices at ${a:g}, ${b:g} and ${c:g} based on conversion and churn. "
        f"Allocate ${ad_spend:,.0f}/day to acquisition channels and ${q_spend:,.0f}/day to quality. "
        f"Use capacity tier {plan['"'capacity']} against peak usage of {daily_peak:,} and quote {ready} enterprise threads. \"
        f\"Watch realized collections, compute cost and support age.\"
    )
    if plan.get(\"discover\"):
        plan[\"rationale\"] += f\" Fund {plan['discover']} market research attempts from this week's cash.\"
    plan[\"forecast\"] = cash_forecast(observation, plan, groups, plan[\"prices\"], margin, expected_acquisition)
    return plan
